head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10104";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_datefmt_cal_intRtDecsnBasDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10104.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_intRtDecsnMiscBasIntNm", fn: function () { return String((dma_pageContext.get("intRtDecsnMiscBasIntNm") ?? "")); } },
        { childId: "ipt_spd", fn: function () { return String((dma_pageContext.get("spd") ?? "")); } },
        { childId: "ipt_uplmtCoupnRt", fn: function () { return String((dma_pageContext.get("uplmtCoupnRt") ?? "")); } },
        { childId: "ipt_lwlmtCoupnRt", fn: function () { return String((dma_pageContext.get("lwlmtCoupnRt") ?? "")); } },
        { childId: "cal_intRtDecsnBasDd", fn: function () { return String((dma_pageContext.get("intRtDecsnBasDd") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_intRtDecsnBasDd
 * @description 초기화 — datefmt cal int Rt Decsn Bas Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_intRtDecsnBasDd = function () { $c.date.checkCalendarFormat("cal_intRtDecsnBasDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.cb_select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10104.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_coupnRtDecsnBasIntCd_onchange
 * @description slc_coupnRtDecsnBasIntCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_coupnRtDecsnBasIntCd_onchange = function(e){
    try {
        scwin.cb_select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10104.slc_coupnRtDecsnBasIntCd_onchange' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.send_form()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10104.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_sendCancel_onclick
 * @description btn_sendCancel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_sendCancel_onclick = function(e){
    try {
        scwin.send_cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10104.btn_sendCancel_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cb_select
 * @description cb select 처리
 * @returns {void}
 * @hidden N
 */
scwin.cb_select = function () {
    if ($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue() === "90") {
        $c.util.getComponent("ipt_intRtDecsnMiscBasIntNm").setStyle("background", "");
        (($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm')) && ($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm')).setDisabled ? ($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm')).setDisabled((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
        int_rt_decsn_misc_bas_int_nm.focus();
    } else {
        $c.util.getComponent("ipt_intRtDecsnMiscBasIntNm").setStyle("background", "#e2e2e2");
        (($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm')) && ($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm')).setDisabled ? ($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
        $c.util.getComponent('ipt_intRtDecsnMiscBasIntNm').setValue("");
    }
};

/**
 * @method
 * @name send_form
 * @description send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send_form = async function () {
    if ($c.str.getByteLength($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue()) === 0) {
        await $c.win.alert("표면이자율결정 기준금리를 입력하세요.");
        $c.util.getComponent("slc_coupnRtDecsnBasIntCd").focus();
        return;
    }
    if ($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue() === "90") {
        if ($c.str.getByteLength($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm').getValue()) === 0) {
            await $c.win.alert("표면이자율결정 기준금리 기타내용을 입력하세요.");
            int_rt_decsn_misc_bas_int_nm.focus();
            return;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_intRtDecsnMiscBasIntNm').getValue()) > 20) {
            await $c.win.alert("표면이자율결정 기준금리 기타내용을 한글 10자, 영문 20자이내로 입력해 주십시오");
            int_rt_decsn_misc_bas_int_nm.focus();
            return;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_intRtDecsnBasDd').getValue()) === 0) {
        await $c.win.alert("최초 표면이자율결정 기준일을 입력하세요.");
        $c.util.getComponent("cal_intRtDecsnBasDd").focus();
        return;
    }
    let int_rt_decsn_misc_bas_int_nm = "";
    if ($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue() === "90") {
        int_rt_decsn_misc_bas_int_nm = $c.util.getComponent('ipt_intRtDecsnMiscBasIntNm').getValue();
    }
    ((scwin.opener().getComponentById("slc_coupnRtDecsnBasIntCd")) || { setValue: function () {} }).setValue($c.util.getComponent('slc_coupnRtDecsnBasIntCd').getValue());
    ((scwin.opener().getComponentById("intRtDecsnMiscBasIntNm")) && (scwin.opener().getComponentById("intRtDecsnMiscBasIntNm")).setValue ? (scwin.opener().getComponentById("intRtDecsnMiscBasIntNm")).setValue(int_rt_decsn_misc_bas_int_nm) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "intRtDecsnMiscBasIntNm"), void (int_rt_decsn_misc_bas_int_nm)));
    ((scwin.opener().getComponentById("slc_spdSgn")) || { setValue: function () {} }).setValue($c.util.getComponent('slc_spdSgn').getValue());
    ((scwin.opener().getComponentById("ipt_spd")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_spd').getValue());
    ((scwin.opener().getComponentById("int_rt_decsn_tm_cd")) || { setValue: function () {} }).setValue($("td#int_rt_decsn_tm_cd input:checked").val());
    ((scwin.opener().getComponentById("ipt_uplmtCoupnRt")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_uplmtCoupnRt').getValue());
    ((scwin.opener().getComponentById("ipt_lwlmtCoupnRt")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_lwlmtCoupnRt').getValue());
    ((scwin.opener().getComponentById("cal_intRtDecsnBasDd")) || { setValue: function () {} }).setValue($c.util.getComponent('cal_intRtDecsnBasDd').getValue());
    $c.win.closePopup();
};

/**
 * @method
 * @name send_cancel
 * @description send cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.send_cancel = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};
